import json,sys,html,re
d=json.load(sys.stdin)
def walk(n,depth=0):
    t=n.get('text') or ''
    t=re.sub('<[^>]+>',' ',html.unescape(t))
    if t.strip(): print('---', n.get('author'),':',t[:800])
    for c in n.get('children',[]): walk(c,depth+1)
walk(d)" | head -60

